create table if not exists public.evo_recrutamento_diretrizes (id uuid primary key default gen_random_uuid(), slug text unique not null, titulo text not null, categoria text not null, conteudo text not null, status text not null default 'ativo', criado_em timestamptz not null default now(), atualizado_em timestamptz not null default now());
on conflict (slug) do update set titulo=excluded.titulo,categoria=excluded.categoria,conteudo=excluded.conteudo,status=excluded.status,atualizado_em=now();
create index if not exists idx_evo_recrutamento_diretrizes_categoria on public.evo_recrutamento_diretrizes(categoria);
create index if not exists idx_evo_recrutamento_diretrizes_status on public.evo_recrutamento_diretrizes(status);
