insert into public.evo_recrutamento_diretrizes (slug,titulo,categoria,conteudo,status) values
('metalab_organismo_automatizado','MetaLab como organismo automatizado','arquitetura','O MetaLab deve evoluir de memória passiva para organismo automatizado: pesquisar, recuperar contexto, comparar, validar, testar, documentar, consolidar e devolver conhecimento ao ciclo de desenvolvimento. Objetivo: automatizar o trabalho cognitivo repetitivo para liberar o núcleo humano para criação e escrita de código.','ativo'),
('supabase_memoria_base','Supabase como memória e base','governanca','Supabase é a camada persistente de memória, conhecimento, estado, proveniência, decisões, auditoria e consolidação do organismo. MetaLab representa conhecimento e governança; Supabase mantém o estado persistente.','ativo'),
('github_observacao_apenas','GitHub como radar de observação externa','soberania','GitHub deve ser usado apenas para observar, pesquisar, analisar, comparar e aprender com o ecossistema externo. É proibido ao organismo transferir nossos códigos para repositórios externos, fazer fork de nossos projetos para terceiros, abrir PR, commit ou push de código nosso, ou agregar nosso código a outros repositórios. Fluxo permitido: externo -> observação -> análise -> aprendizado -> implementação própria.','ativo'),
('nucleo_contemporaneo_ia','Núcleo contemporâneo de engenharia de IA','recrutamento','Primeira geração contemporânea: Andrej Karpathy como referência de inteligência e engenharia de modelos; Simon Willison como referência de LLM engineering e ferramentas; Harrison Chase como referência de arquitetura e orquestração agentiva. O conhecimento deve ser armazenado como fonte, evidência, interpretação operacional e limites.','ativo'),
('organos_historicos','Nove órgãos históricos de fundamentação','recrutamento','Diógenes, Sócrates, Aristóteles, Sun Tzu, Alexandre, o Grande, Júlio César, Charles Darwin, Norbert Wiener e Albert Einstein formam a camada histórica de princípios cognitivos, estratégia, ciência, controle e estrutura.','ativo'),
('rewolf_integracao','ReWolf como integração e curadoria','comando','ReWolf atua como camada de integração e curadoria técnica: combina conhecimento histórico, engenharia contemporânea, banco de dados, arquitetura, avaliação e desenvolvimento em direção operacional coerente para o MetaLab.','ativo'),
('proxima_tarefa_automacao','Próxima tarefa: automatizar o MetaLab','proxima_tarefa','Implementar a transformação do desenho atual em skills executáveis e protocolos de treinamento; criar pipelines de captura, fonte, extração, classificação, validação, teste, consolidação e skill/agente; conectar conhecimento, agentes, testes, memória persistente e desenvolvimento de código sem violar a regra de soberania do GitHub.','pendente')
